/* ============================================================
   05z — СПАМТОН [BIG SHOT]: встроенный аудио-ассет ЗАРЯДА
   Оригинальный звук зарядки (Deltarune charging-shoot) встроен как
   base64 (MP3), чтобы игра работала без внешних файлов.
   Грузится ПОСЛЕ 05-audio.js (Audio3D_SFX уже определён).
   ============================================================ */
const SPAMTON_CHARGE_MP3_B64 = "";
/* предзагрузка ассета при инициализации звука (init вызывается один раз) */
if (typeof Audio3D_SFX !== 'undefined' && Audio3D_SFX.init) {
  const _spamtonOrigInit = Audio3D_SFX.init;
  Audio3D_SFX.init = function () {
    _spamtonOrigInit.call(this);
    if (this._loadSpamtonCharge) this._loadSpamtonCharge();
    if (this._loadSpamtonSfx) this._loadSpamtonSfx();
  };
}
/* ============================================================
   СПАМТОН [BIG SHOT]: встроенные аудио-ассеты ВЫСТРЕЛА и ГИПЕР-ВЫСТРЕЛА
   (оригинальные звуки, base64 MP3 — работают без внешних файлов).
   ============================================================ */
const SPAMTON_SHOT_MP3_B64 = "";
